// FUNCTION: BFME2 0x0044F0B3 size=475 name=?handlePackingProcessing@SpecialAbilityUpdate@@MAE_NXZ evidence=N:ledger
bool SpecialAbilityUpdate::handlePackingProcessing()
{
	const SpecialAbilityUpdateModuleData *data = (const SpecialAbilityUpdateModuleData *)getModuleData();
	if (m_animFrames > 0)
	{
		m_animFrames--;
		if (m_animFrames == 0)
		{
			getObject()->clearModelConditionFlags(ModelConditionFlags(ModelConditionFlags::kInit, 0x60, 0x61, 0x62, 0x63, 0x249, 0x24a, 0x24b, 0x5e));
			if (m_packingState == 2)
			{
				if (data->m_flipObjectAfterUnpacking)
					getObject()->setOrientation(getObject()->getOrientation() + 3.1415927f);
				m_packingState = 4;
			}
			else if (m_packingState == 1)
			{
				if (data->m_flipObjectAfterPacking)
					getObject()->setOrientation(getObject()->getOrientation() + 3.1415927f);
				m_packingState = 3;
				finishAbility();
				return true;
			}
			if (data->m_specialPowerTemplate->getFO()->m_type == (SpecialPowerType)0x1d)
			{
				ObjectID targetID = m_targetID;
				Object *target = TheGameLogic->findObjectByID(targetID);
				if (target == 0
					|| (target->m_specialAbilityReservationOwnerID != INVALID_ID
						&& target->m_specialAbilityReservationOwnerID != getObject()->m_id))
				{
					finishAbility();
					return true;
				}
				Object *object = getObject();
				Object *targetAgain = TheGameLogic->findObjectByID(targetID);
				target->clearModelConditionFlags(ModelConditionFlags(ModelConditionFlags::kInit, 0x6f));
				target->m_specialAbilityReservationOwnerID = getObject()->m_id;
				if (object->m_team != targetAgain->m_team)
					target->clearModelConditionFlags(ModelConditionFlags(ModelConditionFlags::kInit, 0x6e));
				target->setModelConditionFlags(ModelConditionFlags(ModelConditionFlags::kInit, 0x6e));
				object->setModelConditionFlags(ModelConditionFlags(ModelConditionFlags::kInit, 0x70));
			}
			return false;
		}
		if (data->m_loseStealthOnTrigger && m_animFrames < data->m_preTriggerUnstealthFrames)
		{
			StealthUpdate *stealth = (StealthUpdate *)getObject()->rva0028F4BC();
			if (stealth)
				stealth->markAsDetected(0, 1, 0, true);
			TheGameLogic->getManager178()->detected(getObject(), 0, 0, 1);
		}
		return true;
	}
	return false;
}

